// Aplana las conversaciones abiertas y deja solo las que pueden entrar al
// embudo, para no pedir los mensajes de todas en cada vuelta.
const cfg = $('Configuración').first().json;
const ET = [cfg.etiqueta_bienvenida, cfg.etiqueta_seguimiento_1, cfg.etiqueta_seguimiento_2];
const FINALES = [cfg.etiqueta_en_proceso, cfg.etiqueta_agendada, cfg.etiqueta_intervenir];
const max = Number(cfg.max_candidatas);

const salida = [];
for (const it of $input.all()) {
  const payload = it.json?.data?.payload || it.json?.payload || [];
  for (const c of payload) {
    const etiquetas = (c.labels || []).map(String);
    // Si un comercial ya intervino o el lead avanzo, el automatico no toca nada.
    if (FINALES.some((e) => etiquetas.includes(e))) continue;
    const enEmbudo = ET.some((e) => etiquetas.includes(e));
    const meta = c.meta || {};
    const sender = meta.sender || {};
    salida.push({ json: {
      conversacion_id: c.id,
      contacto_id: sender.id ?? null,
      nombre: sender.name ?? '',
      telefono: sender.phone_number ?? '',
      etiquetas,
      // Adopcion: conversaciones sin etiqueta de estado a las que ya escribimos.
      es_adopcion: !enEmbudo && String(cfg.adopcion_automatica) === 'true',
    }});
    if (salida.length >= max) return salida;
  }
}
return salida;

// Maquina de estados del seguimiento, a partir de las etiquetas de la
// conversacion y del ultimo mensaje real (se ignoran notas privadas y
// eventos de actividad del panel).
const cfg = $('Configuración').first().json;
const conv = $('Seleccionar candidatas').item.json;

const horasSeg1 = Number(cfg.horas_seguimiento_1);
const horasSeg2 = Number(cfg.horas_seguimiento_2);
const horaIni = Number(cfg.hora_inicio_envios);
const horaFin = Number(cfg.hora_fin_envios);
const ET_BIENVENIDA = cfg.etiqueta_bienvenida;
const ET_EN_PROCESO = cfg.etiqueta_en_proceso;
const ET_SEG1 = cfg.etiqueta_seguimiento_1;
const ET_SEG2 = cfg.etiqueta_seguimiento_2;

// Horas transcurridas contando solo el horario de envio: si escribimos a las
// 22:00, las horas no corren mientras el cliente duerme.
function horasActivas(desde, hasta) {
  if (!desde || hasta <= desde) return 0;
  let cursor = DateTime.fromSeconds(desde).setZone('Europe/Madrid');
  const fin = DateTime.fromSeconds(hasta).setZone('Europe/Madrid');
  let total = 0, vueltas = 0;
  while (cursor < fin && vueltas < 400) {
    vueltas++;
    const sig = cursor.startOf('day').plus({ days: 1 });
    const tramoFin = sig < fin ? sig : fin;
    const vIni = cursor.startOf('day').plus({ hours: horaIni });
    const vFin = cursor.startOf('day').plus({ hours: horaFin });
    const a = cursor > vIni ? cursor : vIni;
    const b = tramoFin < vFin ? tramoFin : vFin;
    if (b > a) total += b.diff(a, 'hours').hours;
    cursor = tramoFin;
  }
  return total;
}

const resp = $input.item.json || {};
const mensajes = (resp.payload || []).filter((m) => m.message_type !== 2 && m.private !== true);
const entrantes = mensajes.filter((m) => m.message_type === 0);
const salientes = mensajes.filter((m) => m.message_type === 1 || m.message_type === 3);
const ultimoEntrante = entrantes.length ? Math.max(...entrantes.map((m) => m.created_at)) : 0;
const ultimoSaliente = salientes.length ? Math.max(...salientes.map((m) => m.created_at)) : 0;

const ahora = $now.setZone('Europe/Madrid');
const ahoraSeg = Math.floor(ahora.toSeconds());
const horasDesdeSalida = horasActivas(ultimoSaliente, ahoraSeg);

// El cliente ha contestado si ha escrito ALGUNA vez. No vale mirar si el
// ultimo mensaje es suyo: en cuanto el asistente le responde, el ultimo vuelve
// a ser saliente y la conversacion pareceria sin contestar otra vez.
const haContestado = ultimoEntrante > 0;
const podemosEnviar = ahora.hour >= horaIni && ahora.hour < horaFin;

const etiquetas = conv.etiquetas || [];
const nombreCorto = String(conv.nombre || '').split(' ')[0] || String(conv.nombre || '');
const sinEstado = etiquetas.filter((l) => ![ET_BIENVENIDA, ET_SEG1, ET_SEG2].includes(l));
const unicas = (l) => [...new Set(l)];

const base = {
  conversacion_id: conv.conversacion_id,
  contacto_id: conv.contacto_id,
  nombre: conv.nombre,
  telefono: conv.telefono,
  etiquetas_actuales: etiquetas,
  horas_activas_desde_ultimo_envio: Math.round(horasDesdeSalida * 10) / 10,
  ha_contestado: haContestado,
  plantilla: '', idioma: '', param1: '',
};
// Fuera de horario no sale ninguna plantilla. Como el cambio de etiqueta va
// unido al envio, se pospone entero hasta la primera vuelta despues de las 8.
const enEspera = { json: { ...base, accion: 'sin_accion', motivo: 'fuera de horario' } };

if (!conv.es_adopcion) {
  if (haContestado) {
    return { json: { ...base, accion: 'en_proceso',
      etiquetas_finales: unicas([...sinEstado, ET_EN_PROCESO]) } };
  }
  if (etiquetas.includes(ET_SEG2)) return { json: { ...base, accion: 'sin_accion' } };
  if (etiquetas.includes(ET_SEG1)) {
    if (horasDesdeSalida < horasSeg2) return { json: { ...base, accion: 'sin_accion' } };
    if (!podemosEnviar) return enEspera;
    return { json: { ...base, accion: 'seguimiento_2',
      etiquetas_finales: unicas([...sinEstado, ET_SEG2]),
      plantilla: cfg.plantilla_seguimiento_2, idioma: cfg.idioma_seguimiento_2, param1: nombreCorto } };
  }
  if (etiquetas.includes(ET_BIENVENIDA)) {
    if (horasDesdeSalida < horasSeg1) return { json: { ...base, accion: 'sin_accion' } };
    if (!podemosEnviar) return enEspera;
    return { json: { ...base, accion: 'seguimiento_1',
      etiquetas_finales: unicas([...sinEstado, ET_SEG1]),
      plantilla: cfg.plantilla_seguimiento_1, idioma: cfg.idioma_seguimiento_1, param1: nombreCorto } };
  }
  return { json: { ...base, accion: 'sin_accion' } };
}

// Adopcion: conversaciones ya contactadas pero sin etiqueta de estado.
if (!ultimoSaliente || ultimoEntrante > 0) return { json: { ...base, accion: 'sin_accion' } };
// Nunca adoptamos conversaciones antiguas: evita escribir a leads parados
// desde hace dias el dia que se activa el escenario.
if ((ahoraSeg - ultimoSaliente) / 3600 > Number(cfg.horas_max_adopcion)) {
  return { json: { ...base, accion: 'sin_accion' } };
}
if (horasDesdeSalida < horasSeg1) {
  return { json: { ...base, accion: 'adoptar', etiquetas_finales: unicas([...etiquetas, ET_BIENVENIDA]) } };
}
if (!podemosEnviar) return enEspera;
return { json: { ...base, accion: 'seguimiento_1',
  etiquetas_finales: unicas([...sinEstado, ET_SEG1]),
  plantilla: cfg.plantilla_seguimiento_1, idioma: cfg.idioma_seguimiento_1, param1: nombreCorto } };
